select
 (select count(*) from auth.users where id='af360000-0000-4000-8000-000000000001' or lower(email)='guest-delivery-buyer-af360000@example.invalid') users,
 (select count(*) from public.companies where id='af360000-0000-4000-8000-000000000003' or created_by='af360000-0000-4000-8000-000000000001') companies,
 (select count(*) from public.customers where company_id='af360000-0000-4000-8000-000000000003') customers,
 (select count(*) from public.deals where company_id='af360000-0000-4000-8000-000000000003') deals,
 (select count(*) from public.offers where company_id='af360000-0000-4000-8000-000000000003') offers,
 (select count(*) from private.account_approvals where user_id='af360000-0000-4000-8000-000000000001') approvals,
 (select count(*) from private.offer_reviews where company_id='af360000-0000-4000-8000-000000000003') reviews,
 (select count(*) from private.sale_contract_template_versions where company_id='af360000-0000-4000-8000-000000000003') templates,
 (select count(*) from private.sale_contract_drafts where company_id='af360000-0000-4000-8000-000000000003') drafts,
 (select count(*) from private.contract_signings where company_id='af360000-0000-4000-8000-000000000003') signings,
 (select count(*) from private.contract_signatures where actor_user_id='af360000-0000-4000-8000-000000000001') authenticated_signatures,
 (select count(*) from private.contract_signing_audit where actor_user_id='af360000-0000-4000-8000-000000000001') signing_audit,
 (select count(*) from private.transactional_email_outbox where recipient in('guest-delivery-owner-af360000@example.invalid','guest-delivery-buyer-af360000@example.invalid')) outbox,
 (select count(*) from private.guest_document_invitations where company_id='af360000-0000-4000-8000-000000000003') guest_invitations,
 (select count(*) from private.guest_contract_signatures x join private.guest_document_invitations i on i.id=x.invitation_id where i.company_id='af360000-0000-4000-8000-000000000003') guest_signatures,
 (select count(*) from private.guest_document_audit a join private.guest_document_invitations i on i.id=a.invitation_id where i.company_id='af360000-0000-4000-8000-000000000003') guest_audit,
 (select count(*) from private.customer_portal_accounts where email='guest-delivery-buyer-af360000@example.invalid') portal_accounts,
 (select count(*) from private.customer_portal_invitations where company_id='af360000-0000-4000-8000-000000000003') portal_invitations,
 (select count(*) from private.guest_invitation_renewal_audit where company_id='af360000-0000-4000-8000-000000000003') renewal_audit;
